const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const engine=import('data:text/javascript;base64,'+Buffer.from(fs.readFileSync(path.join(__dirname,'../village-simulation.js'),'utf8')).toString('base64'));
const supplies=import('data:text/javascript;base64,'+Buffer.from(fs.readFileSync(path.join(__dirname,'../board-supplies.js'),'utf8')).toString('base64'));
const board=()=>({id:'village',revision:1,population:6,instances:[{instanceId:'home',cardId:'h',cardRevision:1,capabilities:{housing:6}},{instanceId:'garden',cardId:'g',cardRevision:1,capabilities:{garden:12}},{instanceId:'wood',cardId:'w',cardRevision:1,capabilities:{woodland:4}},{instanceId:'workshop',cardId:'p',cardRevision:1,capabilities:{pottery:2,preservation:2},initialStock:{clay:30}},{instanceId:'square',cardId:'s',cardRevision:1,capabilities:{gathering:6}}],connections:['garden','wood','workshop','square'].map(b=>({a:'home',b,valid:true}))});
test('cross-card crafting consumes exact inputs and supports housing, reserve and shared meal',async()=>{const e=await engine,b=board(),s=e.createVillageState(b),before=JSON.stringify(b);const day=e.advanceVillage(s,b);assert.deepEqual(day.stock,{rawFood:4,fuel:2,clay:28,vessels:1,food:2});assert.equal(day.lastDay.workersUsed,4);assert.equal(day.lastDay.unfed,0);assert.equal(s.day,0);assert.equal(JSON.stringify(b),before);let grown=e.advanceVillage(s,b,{days:6});let r=e.inspectVillage(grown,b);assert(r.goals.every(x=>x.ready));const food=grown.stock.food;grown=e.claimVillageGoal(grown,b,'shared-meal');assert.equal(grown.stock.food,food-6);assert.deepEqual(e.claimVillageGoal(grown,b,'shared-meal'),grown);assert.equal(grown.inspiration,1);});
test('disconnected workshop neither grants clay nor crafts; reconnection grants stock only once',async()=>{const e=await engine,b=board();b.connections=b.connections.filter(x=>x.b!=='workshop');let s=e.advanceVillage(e.createVillageState(b),b);assert.equal(s.stock.clay,0);assert.equal(s.stock.vessels,0);assert.equal(s.lastDay.unfed,6);assert(e.inspectVillage(s,b).warnings.some(x=>x.instanceIds.includes('workshop')));b.connections.push({a:'home',b:'workshop',valid:true});s=e.advanceVillage(s,b);assert.equal(s.stock.clay,28);b.connections=b.connections.filter(x=>x.b!=='workshop');s=e.advanceVillage(s,b);b.connections.push({a:'home',b:'workshop',valid:true});s=e.advanceVillage(s,b);assert.equal(s.stock.clay,26);});
test('invalid access edges do not bridge components and missing workers block output',async()=>{const e=await engine,b=board();b.connections.forEach(x=>x.valid=false);let s=e.advanceVillage(e.createVillageState(b),b);assert.equal(s.stock.rawFood,0);b.instances[0].capabilities.housing=1;b.connections.forEach(x=>x.valid=true);s=e.advanceVillage(e.createVillageState(b),b);assert.equal(s.lastDay.workersUsed,1);assert.equal(s.stock.fuel,0);});
test('save reload is deterministic and finite clay eventually blocks pottery',async()=>{const e=await engine,b=board();const first=e.advanceVillage(e.createVillageState(b),b,{days:6});assert.deepEqual(e.advanceVillage(JSON.parse(JSON.stringify(first)),b),e.advanceVillage(first,b));const end=e.advanceVillage(first,b,{days:20});assert.equal(end.stock.clay,0);assert(end.lastDay.jobs.some(x=>x.job==='pottery'&&x.status==='blocked'));});
test('daily batching matches repeated days in inventories, population service and goals',async()=>{const e=await engine,b=board();let s=e.createVillageState(b);for(let i=0;i<6;i++)s=e.advanceVillage(s,b);const batched=e.advanceVillage(e.createVillageState(b),b,{days:6});assert.deepEqual(s.stock,batched.stock);assert.deepEqual(s.lastDay,batched.lastDay);assert.deepEqual(s.claimedGoals,batched.claimedGoals);});
test('reject malformed capabilities, duplicate identities, negative stocks and premature rewards',async()=>{const e=await engine,b=board(),s=e.createVillageState(b);assert.throws(()=>e.claimVillageGoal(s,b,'winter-reserve'));assert.throws(()=>e.advanceVillage({...s,stock:{...s.stock,food:-1}},b));assert.throws(()=>e.advanceVillage(s,b,{days:366}));b.instances.push({...b.instances[0]});assert.throws(()=>e.createVillageState(b));});
test('source revision changes and remove/reinsert same identity cannot mint initial stock',async()=>{const e=await engine,b=board();let s=e.advanceVillage(e.createVillageState(b),b);b.instances[3].cardRevision=2;b.instances[3].initialStock.clay=1000;s=e.advanceVillage(s,b);assert.equal(s.stock.clay,26);assert.equal(s.stockGranted.filter(x=>x==='workshop').length,1);});
test('separate pottery and preservation cards use one finite reserve through reload and goal claims',async()=>{
 const e=await engine,p=await supplies,b=board();
 b.instances[3].capabilities={pottery:2};
 b.instances.push({instanceId:'preserver',cardId:'preservation-storage',cardRevision:1,capabilities:{preservation:2},initialStock:{clay:999}});
 b.connections.push({a:'workshop',b:'preserver',valid:true});
 b.supplies=p.allocateSupplies(p.createSupplies(b.id,{clay:30}),b,'workshop',{clay:30});
 const input=()=>p.withAllocatedSupplies(b,b.supplies);
 let s=e.advanceVillage(e.createVillageState(input()),input(),{days:6});
 assert.equal(s.stock.clay,18);assert.equal(b.supplies.reserve.clay,0);
 assert(e.inspectVillage(s,input()).goals.every(g=>g.ready));
 for(const goal of ['housing','winter-reserve','shared-meal'])s=e.claimVillageGoal(s,input(),goal);
 assert.equal(s.inspiration,3);
 b.simulation=JSON.parse(JSON.stringify(s));
 assert.deepEqual(e.claimVillageGoal(b.simulation,input(),'shared-meal'),s);
 const copy={...b.instances[3],instanceId:'copy',initialStock:{clay:999}};
 b.instances.push(copy);b.connections.push({a:'home',b:'copy',valid:true});
 assert.throws(()=>p.allocateBoardSupplies(b,'copy',{clay:1}),/Insufficient/);
 const after=e.advanceVillage(s,input());assert.equal(after.stock.clay,14);
 assert.equal(after.inspiration,3);assert.equal(after.stockGranted.filter(id=>id==='workshop').length,1);
});
